import React, { useState, useEffect } from 'react';
import axios from 'axios';
import cheerio from 'cheerio'; 

const ContentFetcher = ({ baseUrl, divId, lastNumberRange }) => {
  const [content, setContent] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchContent = async () => {
      setLoading(true);
      setError(null);

      try {
        const fetchedContent = [];
        for (let i = lastNumberRange[0]; i <= lastNumberRange[1]; i++) {
          const url = `${baseUrl}${i}`;
          const response = await axios.get(url, {
            headers: {
              'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36', // Important to avoid being blocked.
            },
          });
          const $ = cheerio.load(response.data);
          const divContent = $(`#${divId}`).html(); // Get the HTML content of the specified div

          if (divContent) {
            fetchedContent.push({ url, content: divContent });
          }
        }
        setContent(fetchedContent);
      } catch (err) {
        setError(err);
      } finally {
        setLoading(false);
      }
    };

    fetchContent();
  }, [baseUrl, divId, lastNumberRange]);

  if (loading) {
    return <div>Loading...</div>;
  }

  if (error) {
    return <div>Error: {error.message}</div>;
  }

  if (renderContent) {
    return renderContent(content); 
  }

};

export default ContentFetcher;
